  8	 */
  9	public class PopulationGenerator
 10	{
 11	    
 12	    /*///////////////////////////////////////////////////////////////
 13	                                 CONSTANTS
 14	    //////////////////////////////////////////////////////////////*/
 15	    
 16	    // The probability that an animal will be created in any given grid position.
 17	    private static final AnimalType[] ANIMAL_SPAWN_ORDER = AnimalType.values();
 18	    // The probability that a plant will be created in any given grid position.
 19	    private static final PlantType[] PLANT_SPAWN_ORDER = PlantType.values();
 20	    // A constant for initial number of infections in the generated population.
 21	    private static final int INITIAL_INFECTION_COUNT = 11;
 22	    
 23	    /*///////////////////////////////////////////////////////////////
 24	                                   STATE
 25	    //////////////////////////////////////////////////////////////*/
 26	    
 27	    private final SimulatorView view;
 28	    private final Field field;
 29	    
 30	    /*///////////////////////////////////////////////////////////////
 31	                                CONSTRUCTOR
 32	    //////////////////////////////////////////////////////////////*/
 33	    
 34	    /**
 35	     * Construct a population generator and set up the colours for representation of each animal class.
 36	     */
 37	    public PopulationGenerator(SimulatorView view, Field field)
 38	    {
 39	        this.view = view;
 40	        this.field = field;
 41	        setUpColors();
 42	    }
 43	    
 44	    /**
 45	     * The RGB colours associated with the given animals and plants passed to the constructor of Color class from awt library.
 46	     */
 47	    private void setUpColors()
 48	    {
 49	        registerColors(AnimalType.values());
 50	        registerColors(PlantType.values());
 51	        view.showColors();
 52	    }
 53	
 54	    /**
 55	     * Register the species colors with the view.
 56	     *
 57	     * @param species the species to register.
 58	     */
 59	    private void registerColors(SpeciesDescriptor[] species)
 60	    {
 61	        for (SpeciesDescriptor descriptor : species) {
 62	            view.registerSpecies(descriptor);
 63	        }
 64	    }
 65	    
 66	    /**
 67	     * Populate the grid with animals and plants, infect the animals.
 68	     * 
 69	     * @param animals The list of Actor objects representing animals in the simulation
 70	     * @param plants The list of Plant objects representing plants in the simulation
 71	     */
 72	    public void populate(List<Actor> animals , List<Actor> plants)
 73	    {
 74	      // Set up a randomizer and populate the field from the species registries.
 75	      Random rand = Randomizer.getRandom();
 76	      field.clear();
 77	      
 78	      // Nested loop to go through every location on the grid and generate an animal of a certain class 
 79	      // based on a comparison of randomised double with the creation probability of every animal
 80	      for(int row = 0; row < field.getDepth(); row++) {
 81	          for(int col = 0; col < field.getWidth(); col++) {
 82	              Location location = new Location(row, col);
 83	              Animal spawnedAnimal = spawnAnimal(rand, location);
 84	              if(spawnedAnimal != null) {
 85	                  animals.add(spawnedAnimal);
 86	              }
 87	          }
 88	      }
 89	        
 90	      // A loop to go through the list of generated animals and infect 11 animals
 91	      for (int i = 0; i < INITIAL_INFECTION_COUNT && i < animals.size(); i++) {
 92	          Animal animal = (Animal) (animals.get(i));
 93	          animal.setInfectionTimestamp(0);
 94	      }
 95	      
 96	      // Nested loop to go through every location on the grid and generate a plant of a certain class 
 97	      // based on a comparison of randomised double with the creation probability of every plant
 98	      for(int row = 0; row < field.getDepth(); row++) {
 99	          for(int col = 0; col < field.getWidth(); col++) {
100	              Location location = new Location(row, col);
101	              Plant spawnedPlant = spawnPlant(rand, location);
102	              if(spawnedPlant != null) {
103	                  plants.add(spawnedPlant);
104	              }
105	            }
106	        }
107	    } 
108	
109	    /**
110	     * Try to create an animal at the current location.
111	     *
112	     * @param rand random source used to decide whether spawning occurs.
113	     * @param location location to populate.
114	     * @return the spawned animal, or null if no spawn occurs.
115	     */
116	    private Animal spawnAnimal(Random rand, Location location)
117	    {
118	        for(AnimalType type : ANIMAL_SPAWN_ORDER) {
119	            if(rand.nextDouble() <= type.getSpawnProbability()) {
120	                return type.createWithRandomGender(field, location);
121	            }
122	        }
123	        return null;
124	    }
125	
126	    /**
127	     * Try to create a plant at the current location.
128	     *
129	     * @param rand random source used to decide whether spawning occurs.
130	     * @param location location to populate.
131	     * @return the spawned plant, or null if no spawn occurs.
132	     */
133	    private Plant spawnPlant(Random rand, Location location)
134	    {
135	        for(PlantType type : PLANT_SPAWN_ORDER) {
136	            if(rand.nextDouble() <= type.getSpawnProbability()) {
137	                return type.createForPopulation(field, location);
138	            }
139	        }
140	        return null;

